package academic.cafecatchtable.domain;

import jakarta.persistence.*;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.NoArgsConstructor;

/**
 * CAFE (FR-04, FR-08) — Document/01_create_oracle_user.sql
 * 컬럼: CAFE_ID(GENERATED BY DEFAULT AS IDENTITY) / OWNER_ID(FK → OWNER) / CAFE_NAME(100) / ADDRESS(255)
 *      / PHONE(NOT NULL) / START_TIME, END_TIME (VARCHAR2(5) 'HH24:MI', 00:00~23:59, END > START)
 *      / OPERATING_DAYS ('Mon,Tue,...' — 프로시저가 UPPER 로 비교하므로 대소문자 무관)
 */
@Entity
@Table(name = "CAFE")
@Getter
@NoArgsConstructor(access = AccessLevel.PROTECTED)
public class Cafe {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "CAFE_ID")
    private Long cafeId;

    @Column(name = "OWNER_ID", nullable = false)
    private String ownerId;

    @Column(name = "CAFE_NAME", nullable = false)
    private String cafeName;

    @Column(name = "ADDRESS", nullable = false)
    private String address;

    @Column(name = "PHONE")
    private String phone;

    @Column(name = "START_TIME", nullable = false)
    private String startTime;

    @Column(name = "END_TIME", nullable = false)
    private String endTime;

    @Column(name = "OPERATING_DAYS", nullable = false)
    private String operatingDays;

    public static Cafe create(String ownerId, String cafeName, String address, String phone,
                              String startTime, String endTime, String operatingDays) {
        Cafe c = new Cafe();
        c.ownerId = ownerId;
        c.update(cafeName, address, phone, startTime, endTime, operatingDays);
        return c;
    }

    public void update(String cafeName, String address, String phone,
                       String startTime, String endTime, String operatingDays) {
        this.cafeName = cafeName;
        this.address = address;
        this.phone = phone;
        this.startTime = startTime;
        this.endTime = endTime;
        this.operatingDays = operatingDays;
    }

    public boolean isOwnedBy(String memberId) {
        return ownerId != null && ownerId.equals(memberId);
    }
}
